{"file_path":"src/address.js","content":"/**
 * Cell addresses: parsing, canonicalisation, ordering, and range expansion.
 */

/** Convert a 1-based bijective base-26 column number to letters (1 -> A, 27 -> AA). */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    n -= 1
    s = String.fromCharCode(65 + (n % 26)) + s
    n = Math.floor(n / 26)
  }
  return s
}

/** Convert column letters ("A".."ZZ") to their 1-based bijective base-26 number. */
export function colToNum(col) {
  let n = 0
  for (const ch of col) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/**
 * Parse a bare word as an address. Returns { col, row, colNum } when it is
 * one or two letters followed by one to three digits naming a row of at
 * least 1, uppercased; otherwise returns null (the word names an address
 * outside the addressable range).
 */
export function parseAddressWord(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = m[1].toUpperCase()
  return { col, row, colNum: colToNum(col) }
}

/** Canonical "COLROW" key for an address, e.g. { col: 'A', row: 1 } -> 'A1'. */
export function addressKey(addr) {
  return addr.col + String(addr.row)
}

/** Compare two addresses in ascending column then row order. */
export function compareAddresses(a, b) {
  if (a.colNum !== b.colNum) return a.colNum - b.colNum
  return a.row - b.row
}

/**
 * Expand a range node's two corner words into the sorted list of addresses
 * it covers, in ascending column then row order, whichever corner each was
 * written from. Returns null when either corner is outside the addressable
 * range.
 */
export function expandRange(fromWord, toWord) {
  const a = parseAddressWord(fromWord)
  const b = parseAddressWord(toWord)
  if (!a || !b) return null
  const colMin = Math.min(a.colNum, b.colNum)
  const colMax = Math.max(a.colNum, b.colNum)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const result = []
  for (let c = colMin; c <= colMax; c++) {
    const col = numToCol(c)
    for (let r = rowMin; r <= rowMax; r++) {
      result.push({ col, row: r, colNum: c })
    }
  }
  return result
}
"}

