{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after a leading `=`).
 */

export class LexError extends Error {}

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR = new Set(['(', ')', ',', ':', '^', '*', '/', '+', '-', '=', '<', '>'])

/** Split a formula body into tokens, skipping spaces and tabs anywhere. */
export function tokenize(str) {
  const tokens = []
  let i = 0
  while (i < str.length) {
    const c = str[i]
    if (c === ' ' || c === '\t') {
      i += 1
      continue
    }
    if (c >= '0' && c <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(str.slice(i))
      tokens.push({ type: 'NUM', value: parseFloat(m[0]) })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(str.slice(i))
      tokens.push({ type: 'WORD', value: m[0] })
      i += m[0].length
      continue
    }
    const two = str.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR.has(c)) {
      if (c === '(') tokens.push({ type: 'LP', value: c })
      else if (c === ')') tokens.push({ type: 'RP', value: c })
      else if (c === ',') tokens.push({ type: 'COMMA', value: c })
      else if (c === ':') tokens.push({ type: 'COLON', value: c })
      else tokens.push({ type: 'OP', value: c })
      i += 1
      continue
    }
    throw new LexError(`unexpected character ${c}`)
  }
  return tokens
}
"}

