chunk.argumentsDelta:
{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, producing an AST or throwing
 * ParseError when the grammar rejects the input. Precedence, loosest to
 * tightest: comparisons, `+`/`-`, `*`/`/`, `^` (right-associative), and a
 * leading unary `+`/`-` (which binds tighter than `^`).
 *
 * A range (`A1:B3`) is only accepted where it stands alone as a whole call
 * argument; anywhere else the leftover `:` token fails to parse, making the
 * cell `#ERR!` as the specification requires.
 */
import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const KEYWORDS = new Set(['TRUE', 'FALSE'])
const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  parseProgram() {
    const expr = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing tokens')
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && (this.peek().type === 'OP') && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'cmp', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
