{"file_path":"src/values.js","content":"/**
 * Tagged runtime values: numbers, text, booleans and errors, plus the
 * coercion and comparison rules the specification defines for them.
 */

export const numVal = (v) => ({ t: 'num', v })
export const textVal = (v) => ({ t: 'text', v })
export const boolVal = (v) => ({ t: 'bool', v })
export const errVal = (v) => ({ t: 'err', v })

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

/** A number that is not finite (from a bad division or overflow) is #DIV/0!. */
export function numFinite(n) {
  if (!Number.isFinite(n)) return errVal('#DIV/0!')
  return numVal(n)
}

/** Read a value as a number: booleans are 1/0, text is #VALUE!, errors pass through. */
export function toNumber(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return numVal(v.v ? 1 : 0)
  if (v.t === 'text') return errVal('#VALUE!')
  return v
}

function kindRank(v) {
  if (v.t === 'num') return 0
  if (v.t === 'text') return 1
  return 2
}

/** Compare two non-error values per the specification's total order. Returns -1, 0 or 1. */
export function compareValues(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  const av = a.v ? 1 : 0
  const bv = b.v ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}

/** Format a number as JavaScript would after rounding it to ten significant digits. */
export function formatNumber(n) {
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

/** Print any value per the `values` mode rules. */
export function formatValue(v) {
  if (v.t === 'num') return formatNumber(v.v)
  if (v.t === 'text') return v.v
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}
