{"file_path":"src/evaluator.js","content":"/**
 * Evaluates a parsed sheet: resolves each cell's value lazily, memoizing
 * results and detecting reference cycles.
 */
import { parseAddressWord, addressKey, expandRange } from './address.js'
import { numVal, boolVal, errVal, numFinite, toNumber, compareValues } from './values.js'

class CycleSignal {
  constructor(origin) {
    this.origin = origin
  }
}

const COMPARISON_APPLY = {
  '=': (c) => c === 0,
  '<>': (c) => c !== 0,
  '<': (c) => c < 0,
  '<=': (c) => c <= 0,
  '>': (c) => c > 0,
  '>=': (c) => c >= 0,
}

export class Evaluator {
  /** @param {Map<string, object>} cells keyed by canonical address, each { isFormula, ast, parseFailed, literalValue } */
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.state = new Map()
  }

  evaluateAddress(key) {
    if (this.state.get(key) === 'done') return this.cache.get(key)
    if (this.state.get(key) === 'visiting') throw new CycleSignal(key)
    this.state.set(key, 'visiting')
    let result
    try {
      const cell = this.cells.get(key)
      if (!cell) {
        result = numVal(0)
      } else if (cell.parseFailed) {
        result = errVal('#ERR!')
      } else if (!cell.isFormula) {
        result = cell.literalValue
      } else {
        result = this.evalNode(cell.ast)
      }
    } catch (e) {
      if (e instanceof CycleSignal) {
        this.cache.set(key, errVal('#CYCLE!'))
        this.state.set(key, 'done')
        if (e.origin === key) return this.cache.get(key)
        throw e
      }
      throw e
    }
    this.cache.set(key, result)
    this.state.set(key, 'done')
    return result
  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return numVal(node.value)
      case 'bool':
        return boolVal(node.value)
      case 'addr': {
        const addr = parseAddressWord(node.word)
        if (!addr) return errVal('#REF!')
        return this.evaluateAddress(addressKey(addr))
      }
      case 'unary': {
        const operand = this.evalNode(node.operand)
        if (operand.t === 'err') return operand
        const n = toNumber(operand)
        if (n.t === 'err') return n
        return numFinite(node.op === '-' ? -n.v : n.v)
      }
      case 'bin': {
        const l = this.evalNode(node.left)
        if (l.t === 'err') return l
        const ln = toNumber(l)
        if (ln.t === 'err') return ln
        const r = this.evalNode(node.right)
        if (r.t === 'err') return r
        const rn = toNumber(r)
        if (rn.t === 'err') return rn
        switch (node.op) {
          case '+':
            return numFinite(ln.v + rn.v)
          case '-':
            return numFinite(ln.v - rn.v)
          case '*':
            return numFinite(ln.v * rn.v)
          case '/':
            if (rn.v === 0) return errVal('#DIV/0!')
            return numFinite(ln.v / rn.v)
          case '^':
            return numFinite(Math.pow(ln.v, rn.v))
          default:
            throw new Error(`unknown operator ${node.op}`)
        }
      }
      case 'cmp': {
        const l = this.evalNode(node.left)
        if (l.t === 'err') return l
        const r = this.evalNode(node.right)
        if (r.t === 'err') return r
        const c = compareValues(l, r)
        return boolVal(COMPARISON_APPLY[node.op](c))
      }
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  /** Evaluate an argument that must be a single scalar: a range must cover exactly one cell. */
  evalScalarArg(node) {
    if (node.type === 'range') {
      const cells = expandRange(node.from, node.to)
      if (!cells) return errVal('#REF!')
      if (cells.length !== 1) return errVal('#VALUE!')
      return this.evaluateAddress(addressKey(cells[0]))
    }
    return this.evalNode(node)
  }

  /**
   * Evaluate a list of aggregate arguments left to right, expanding ranges
   * into their covered cells. Stops at the first error found, which wins
   * over everything else. Returns { error } or { values }.
   */
  collectArgValues(argNodes) {
    const values = []
    for (const arg of argNodes) {
      if (arg.type === 'range') {
        const cells = expandRange(arg.from, arg.to)
        if (!cells) return { error: '#REF!' }
        for (const addr of cells) {
          const v = this.evaluateAddress(addressKey(addr))
          if (v.t === 'err') return { error: v.v }
          values.push(v)
        }
      } else {
        const v = this.evalNode(arg)
        if (v.t === 'err') return { error: v.v }
        values.push(v)
      }
    }
    return { values }
  }

  evalCall(node) {
    const name = node.name
    const args = node.args
    switch (name) {
      case 'SUM':
      case 'MIN':
      case 'MAX':
      case 'AVG': {
        if (args.length < 1) return errVal('#ERR!')
        const r = this.collectArgValues(args)
        if (r.error) return errVal(r.error)
        const nums = []
        for (const v of r.values) {
          const n = toNumber(v)
          if (n.t === 'err') return n
          nums.push(n.v)
        }
        if (name === 'SUM') return numFinite(nums.reduce((a, b) => a + b, 0))
        if (name === 'MIN') return numFinite(Math.min(...nums))
        if (name === 'MAX') return numFinite(Math.max(...nums))
        return numFinite(nums.reduce((a, b) => a + b, 0) / nums.length)
      }
      case 'COUNT': {
        if (args.length < 1) return errVal('#ERR!')
        const r = this.collectArgValues(args)
        if (r.error) return errVal(r.error)
        let c = 0
        for (const v of r.values) if (v.t === 'num') c += 1
        return numVal(c)
      }
      case 'ABS': {
        if (args.length !== 1) return errVal('#ERR!')
        const v = this.evalScalarArg(args[0])
        if (v.t === 'err') return v
        const n = toNumber(v)
        if (n.t === 'err') return n
        return numFinite(Math.abs(n.v))
      }
      case 'IF': {
        if (args.length !== 3) return errVal('#ERR!')
        const cond = this.evalScalarArg(args[0])
        if (cond.t === 'err') return cond
        let taken
        if (cond.t === 'bool') taken = cond.v
        else if (cond.t === 'num') taken = cond.v !== 0
        else return errVal('#VALUE!')
        return this.evalScalarArg(taken ? args[1] : args[2])
      }
      default:
        return errVal('#NAME?')
    }
  }
}

/**
 * Collect the distinct addresses a formula's AST names directly, ranges
 * expanded, ordered by column then row. Addresses outside the addressable
 * range are omitted.
 */
export function collectDeps(ast) {
  const seen = new Map()
  const add = (addr) => {
    seen.set(addressKey(addr), addr)
  }
  const walk = (node) => {
    switch (node.type) {
      case 'num':
      case 'bool':
        return
      case 'addr': {
        const addr = parseAddressWord(node.word)
        if (addr) add(addr)
        return
      }
      case 'range': {
        const cells = expandRange(node.from, node.to)
        if (cells) for (const c of cells) add(c)
        return
      }
      case 'unary':
        walk(node.operand)
        return
      case 'bin':
      case 'cmp':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const a of node.args) walk(a)
        return
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }
  walk(ast)
  return [...seen.values()].sort((a, b) => a.colNum - b.colNum || a.row - b.row)
}
"}

