    if (cells.has(key)) throw new SheetError(lineNo, `cell ${key} is declared twice`)

    let cell
    if (content.startsWith('=')) {
      try {
        const ast = parseFormula(content.slice(1))
        cell = { isFormula: true, ast, parseFailed: false }
      } catch (e) {
        if (e instanceof ParseError) cell = { isFormula: true, parseFailed: true }
        else throw e
      }
    } else {
      cell = { isFormula: false, literalValue: classifyLiteral(content) }
    }
    cells.set(key, cell)
    addrs.set(key, addr)
  }

  const order = [...addrs.values()].sort(compareAddresses)
  return { cells, order }
}
"}

