      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const out = []
  if (mode === 'values') {
    const evaluator = new Evaluator(sheet.cells)
    for (const addr of sheet.order) {
      const key = addressKey(addr)
      const value = evaluator.evaluateAddress(key)
      out.push(`${key}=${formatValue(value)}`)
    }
  } else {
    for (const addr of sheet.order) {
      const key = addressKey(addr)
      const cell = sheet.cells.get(key)
      const deps = cell.isFormula && !cell.parseFailed ? collectDeps(cell.ast) : []
      const depStr = deps.map((d) => ` ${addressKey(d)}`).join('')
      out.push(`${key}:${depStr}`)
    }
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
}

